package com.zipbug.base.licenses

/**
 * Resolves license metadata for apps GENERATED by Zip_Bug (App Creator /
 * AppScaffolder) and builds the per-app license manifest + notices asset
 * that are packaged into every generated project.
 *
 * The known-metadata table below mirrors the curated table in
 * scripts/generate-licenses.py; verify-project.py fails CI if a bundled
 * license entry is missing here. Any coordinate that is not known is
 * reported as "License review required" — it is never silently relabelled.
 */
object GeneratedLicenseManifest {

    data class KnownLicense(
        val displayName: String,
        val author: String,
        val license: String,
        val licenseUrl: String,
        val category: String
    )

    data class ResolvedDependency(
        val coordinate: String,
        val version: String,
        val known: KnownLicense?
    ) {
        val licenseName: String
            get() = known?.license ?: LicenseEntry.REVIEW_REQUIRED
        val isReviewRequired: Boolean
            get() = known == null
    }

    const val REVIEW_REQUIRED = LicenseEntry.REVIEW_REQUIRED

    /** Fixed core of every generated app (mirrors AppScaffolder). */
    val CORE_DEPENDENCIES: List<String> = listOf(
        "androidx.core:core-ktx:1.13.1",
        "androidx.appcompat:appcompat:1.7.0",
        "com.google.android.material:material:1.12.0",
        "org.jetbrains.kotlin:kotlin-stdlib:1.9.24"
    )

    private const val APACHE = "Apache License 2.0"
    private const val APACHE_URL = "https://www.apache.org/licenses/LICENSE-2.0"
    private const val AOSP = "The Android Open Source Project"

    private fun apache(displayName: String, author: String) =
        KnownLicense(displayName, author, APACHE, APACHE_URL, "apache")

    val KNOWN: Map<String, KnownLicense> = mapOf(
        "androidx.core:core-ktx" to apache("Core KTX", AOSP),
        "androidx.appcompat:appcompat" to apache("AppCompat", AOSP),
        "androidx.activity:activity-ktx" to apache("Activity KTX", AOSP),
        "androidx.fragment:fragment-ktx" to apache("Fragment KTX", AOSP),
        "androidx.lifecycle:lifecycle-runtime-ktx" to
            apache("Lifecycle Runtime KTX", AOSP),
        "androidx.lifecycle:lifecycle-viewmodel-ktx" to
            apache("Lifecycle ViewModel KTX", AOSP),
        "com.google.android.material:material" to
            apache("Material Components for Android", "Google LLC"),
        "androidx.room:room-runtime" to apache("Room Runtime", AOSP),
        "androidx.room:room-ktx" to apache("Room KTX", AOSP),
        "androidx.room:room-compiler" to apache("Room Compiler", AOSP),
        "com.squareup.okhttp3:okhttp" to apache("OkHttp", "Square, Inc."),
        "com.github.bumptech.glide:glide" to KnownLicense(
            "Glide",
            "Bumptech",
            "BSD 3-Clause License",
            "https://opensource.org/licenses/BSD-3-Clause",
            "bsd"
        ),
        "org.jetbrains.kotlinx:kotlinx-coroutines-android" to
            apache("Kotlinx Coroutines Android", "JetBrains s.r.o."),
        "org.jetbrains.kotlin:kotlin-stdlib" to
            apache("Kotlin Standard Library", "JetBrains s.r.o."),
        "junit:junit" to KnownLicense(
            "JUnit 4",
            "JUnit Team",
            "Eclipse Public License 1.0",
            "https://www.eclipse.org/legal/epl-v10.html",
            "other"
        ),
        "org.json:json" to KnownLicense(
            "JSON in Java (org.json)",
            "JSON.org",
            "The JSON License",
            "https://www.json.org/license.html",
            "other"
        )
    )

    private val COORDINATE =
        Regex("^([A-Za-z0-9_.\-]+):([A-Za-z0-9_.\-]+):([A-Za-z0-9_.+\-]+)$")

    /** Resolve full "group:artifact:version" coordinates, de-duplicated. */
    fun resolve(coordinates: List<String>): List<ResolvedDependency> {
        val seen = LinkedHashMap<String, ResolvedDependency>()
        for (raw in coordinates) {
            val m = COORDINATE.matchEntire(raw.trim()) ?: continue
            val ga = "${m.groupValues[1]}:${m.groupValues[2]}"
            if (ga !in seen) {
                seen[ga] = ResolvedDependency(
                    coordinate = ga,
                    version = m.groupValues[3],
                    known = KNOWN[ga]
                )
            }
        }
        return seen.values.toList()
    }

    fun unknownCount(resolved: List<ResolvedDependency>): Int =
        resolved.count { it.isReviewRequired }

    /** license-manifest.json content stored with the generated project. */
    fun buildManifestJson(
        appName: String,
        packageName: String,
        features: List<String>,
        coordinates: List<String>
    ): String {
        val resolved = resolve(coordinates)
        val sb = StringBuilder()
        sb.append("{\n")
        sb.append("  \"appName\": ").append(json(appName)).append(",\n")
        sb.append("  \"packageName\": ").append(json(packageName)).append(",\n")
        sb.append("  \"features\": [")
        sb.append(features.joinToString(", ") { json(it) })
        sb.append("],\n")
        sb.append("  \"libraries\": ").append(resolved.size).append(",\n")
        sb.append("  \"unknown\": ").append(unknownCount(resolved)).append(",\n")
        sb.append("  \"noticesReady\": true,\n")
        sb.append("  \"dependencies\": [\n")
        resolved.forEachIndexed { index, dep ->
            sb.append("    {\n")
            sb.append("      \"name\": ").append(json(dep.coordinate)).append(",\n")
            sb.append("      \"version\": ").append(json(dep.version)).append(",\n")
            sb.append("      \"license\": ").append(json(dep.licenseName)).append("\n")
            sb.append("    }")
            if (index < resolved.size - 1) sb.append(",")
            sb.append("\n")
        }
        sb.append("  ]\n")
        sb.append("}\n")
        return sb.toString()
    }

    /** assets/third_party_notices.txt content for a generated app. */
    fun buildNotices(appName: String, coordinates: List<String>): String {
        val resolved = resolve(coordinates)
        val sb = StringBuilder()
        sb.append("THIRD-PARTY NOTICES — ").append(appName).append("\n\n")
        sb.append("This app was generated with Zip_Bug and includes the ")
        sb.append("open source libraries listed below.\n\n")
        sb.append("Libraries: ").append(resolved.size)
        sb.append("  Unknown: ").append(unknownCount(resolved)).append("\n\n")
        for (dep in resolved) {
            sb.append("=".repeat(72)).append("\n")
            val display = dep.known?.displayName ?: dep.coordinate
            sb.append(display)
            sb.append(" (").append(dep.coordinate).append(":")
            sb.append(dep.version).append(")\n")
            if (dep.known != null) {
                sb.append("Author: ").append(dep.known.author).append("\n")
                sb.append("License: ").append(dep.known.license).append("\n")
                sb.append("License URL: ").append(dep.known.licenseUrl).append("\n")
            } else {
                sb.append("License: ").append(REVIEW_REQUIRED).append("\n")
                sb.append(
                    "The license for this dependency could not be determined " +
                        "automatically. Review it before redistributing this app.\n"
                )
            }
            sb.append("\n")
        }
        return sb.toString()
    }

    private fun json(value: String): String =
        "\"" + value
            .replace("\\", "\\\\")
            .replace("\"", "\\\"")
            .replace("\n", "\\n") + "\""
}
